export interface TflOrdersV1OrderItem {
	/**
	 * SovConnector.connectorId of the thefulfillmentlab connector that fetched this order item
	 */
	connectorId: string;
	/**
	 * OUR row bookkeeping: when this row was first written. Not a GFS field
	 */
	createdAt: InstantColumn;
	/**
	 * The full verbatim `items[]` element from the order detail payload; persisted as JSONB. Keeps the raw timestamp strings, so the UTC reading above is recoverable from stored data without a re-fetch. Typed `Unknown` because no vendored API type exists to pin a struct against
	 */
	doc: Json;
	/**
	 * SOURCE ZONE: UTC, parsed directly with NO localisation. `items[].createdAt`. MEASURED (eval03) within 0-7 ms of the parent order's `createdAt` on 14/14 rows, and that parent field is itself measured UTC. Prefixed `gfs` so it does not collide with our own `createdAt` bookkeeping column
	 */
	gfsCreatedAt: InstantColumn;
	/**
	 * SOURCE ZONE: UTC, parsed directly with NO localisation — DELIBERATELY UNLIKE the order-level `gfsModifiedAt`, which is Eastern. ONE PAYLOAD CARRIES BOTH READINGS: MEASURED (eval03), `items[].modifiedAt` sits within milliseconds of the order's UTC `createdAt` on 14/14 rows while the same rows' order-level `modifiedAt` reads four hours behind. Localising this value from America/New_York would shift it 4-5 hours
	 */
	gfsModifiedAt: InstantColumn;
	/**
	 * `items[].id`, the line's own GFS id. MEASURED unique across the corpus
	 */
	id: number;
	/**
	 * `items[].name`; the product name as the cart supplied it
	 */
	name: string | null;
	/**
	 * `items[].orderId`, joining to `tfl_orders_v1__Order.id`. No foreign key is declared, matching the wmt_* target-table precedent
	 */
	orderId: number;
	/**
	 * `items[].quantity`; MEASURED integral (1-5) across the detail corpus
	 */
	quantity: number;
	/**
	 * `items[].retailValue`, the line's retail amount. MEASURED NON-INTEGRAL (1.47, 41.79), so Schema.Int would truncate it. Stored DOUBLE PRECISION rather than NUMERIC: the repo's position is that money-adjacent analytics values take DOUBLE PRECISION, which postgres.js returns as a real JS number, while NUMERIC comes back as a string
	 */
	retailValue: number;
	/**
	 * `items[].sku`, joining to `tfl_products_v1__Sku.sku` by convention
	 */
	sku: string | null;
	/**
	 * OUR row bookkeeping: when this row was last written. Not a GFS field
	 */
	updatedAt: InstantColumn;
}

export interface TflOtsShipmentsV1OtsShipment {
	/**
	 * `otsShipment.category`; observed Disposal / Legacy / Outbound
	 */
	category: string | null;
	/**
	 * `otsShipment.categoryId`; MEASURED 1-3
	 */
	categoryId: number;
	/**
	 * `otsShipment.clientReferenceId`; merchant-supplied free text, frequently the empty string
	 */
	clientReferenceId: string | null;
	/**
	 * SOURCE ZONE: UTC, MEASURED — the detail route serialises an explicit `Z` (eval03), which the list route truncates. `otsShipment.completedDate`; MEASURED null on 16/371 rows
	 */
	completedDate: InstantColumn | null;
	/**
	 * SovConnector.connectorId of the thefulfillmentlab connector that fetched this OTS shipment
	 */
	connectorId: string;
	/**
	 * OUR row bookkeeping: when this row was first written. Not a GFS field
	 */
	createdAt: InstantColumn;
	/**
	 * OURS, NOT GFS'S: when this shipment's detail route was successfully fetched and its items written. NULL means still pending. MUST be excluded from `updateColumns` on the header upsert, or the daily header refresh nulls it on any doc change and details are re-fetched forever. Stamped AFTER the child-item upsert succeeds, so a crash in between leaves it null and the next run retries
	 */
	detailsFetchedAt: InstantColumn | null;
	/**
	 * The full verbatim OTS shipment payload from the API; persisted as JSONB, including the raw `createdAt` string that makes the UTC inference above reversible. Typed `Unknown` because no vendored API type exists to pin a struct against
	 */
	doc: Json;
	/**
	 * SOURCE ZONE: UTC BY INFERENCE, NOT BY MEASUREMENT — parsed directly with no localisation. `otsShipment.createdAt` has no partner stamp to difference against, so its zone cannot be measured. The inference's basis: every `createdAt` measured anywhere in this API is UTC, and the same payload's `completedDate` carries an explicit Z on the detail route, so the serializer family is UTC and a wall-time reading has zero supporting instances. If wrong, the error is a bounded 4-5 hour shift recoverable from `doc`
	 */
	gfsCreatedAt: InstantColumn;
	/**
	 * `otsShipment.hubspotTicketNumber`; a free-text field that MEASURED holds non-numeric values such as "email" and the empty string, so it must not be parsed as a number
	 */
	hubspotTicketNumber: string | null;
	/**
	 * `otsShipment.id`, GFS's own id. MEASURED unique 371/371
	 */
	id: number;
	/**
	 * `otsShipment.status`; observed Canceled / Completed / Pulled. A vendor string, so NOT a Schema.Literal — a new status must not become a decode failure
	 */
	status: string | null;
	/**
	 * `otsShipment.statusId`; MEASURED 3-5
	 */
	statusId: number;
	/**
	 * OUR row bookkeeping: when this row was last written. Not a GFS field
	 */
	updatedAt: InstantColumn;
	/**
	 * `otsShipment.warehouse` (observed: Tampa). Note the name has no `Name` suffix here, unlike `warehouseName` elsewhere in this API — the payload field is spelled this way
	 */
	warehouse: string | null;
	/**
	 * `otsShipment.warehouseId`; MEASURED constant 1 across the corpus
	 */
	warehouseId: number;
}

export interface TflOtsShipmentsV1OtsShipmentItem {
	/**
	 * SovConnector.connectorId of the thefulfillmentlab connector that fetched this OTS item
	 */
	connectorId: string;
	/**
	 * OUR row bookkeeping: when this row was first written. Not a GFS field
	 */
	createdAt: InstantColumn;
	/**
	 * The verbatim `items[]` element from the OTS detail payload; persisted as JSONB. When several elements were aggregated into one row this holds the LAST of them, so the aggregated `quantity` column can exceed the quantity inside `doc` — the only place in this connector where a column and `doc` legitimately disagree. Typed `Unknown` because no vendored API type exists to pin a struct against
	 */
	doc: Json;
	/**
	 * The parent shipment's `otsShipment.id`, joining to `tfl_otsShipments_v1__OtsShipment.id`
	 */
	otsShipmentId: number;
	/**
	 * `items[].productId`, joining to `tfl_products_v1__Inventory.productId`. It is in the key because the payload carries NO line id — there is no alternative — which is why a repeated productId must be aggregated by the transform rather than written twice
	 */
	productId: number;
	/**
	 * `items[].productName`, promoted for readability only. NOT an identity: `tfl_products_v1__Inventory` is the authoritative product dimension and `productId` is the join key
	 */
	productName: string | null;
	/**
	 * `items[].quantity`, MEASURED integral. Holds the SUM across every `items[]` entry sharing this productId within the shipment, because the payload has no line id to separate them by
	 */
	quantity: number;
	/**
	 * OUR row bookkeeping: when this row was last written. Not a GFS field
	 */
	updatedAt: InstantColumn;
}

