export interface WmtInventoryV3Wfs {
	availToSellQty: number | null;
	/**
	 * OURS, not from the payload: SovConnector.connectorId of the walmart_marketplace connector that took the snapshot; the tenant key
	 */
	connectorId: string;
	createdAt: InstantColumn;
	/**
	 * THE NODE (`node`) verbatim, NOT the item — the row's grain IS the node, so the node is its verbatim payload. Consequence: sibling nodes of the same item are not recoverable from any single row's doc, and sku/offerId appear only as their own columns. Persisted as JSONB; typed `Unknown` because no vendored API type exists to pin a struct against
	 */
	doc: Json;
	firstInStockDate: InstantColumn | null;
	modifiedDate: InstantColumn | null;
	offerId: string | null;
	onHandQty: number | null;
	/**
	 * NODE-level (`node.shipNode`). The node's IDENTIFIER — distinct from shipNodeType, which is its class. IN THE PRIMARY KEY: two nodes of the same shipNodeType but different shipNode are DISTINCT rows, not a collision. The API marks it optional; when the payload omits it the Worker writes the empty-string SENTINEL '' (a PK column cannot be NULL), so '' means `node.shipNode` was absent
	 */
	shipNode: string;
	/**
	 * NODE-level (`node.shipNodeType`). From the RESPONSE BODY, NEVER from the request: /v3/fulfillment/inventory takes no shipNodeType parameter (that is /v3/orders). The node's CLASS, not its identifier
	 */
	shipNodeType: string;
	/**
	 * ITEM-level (`item.sku`)
	 */
	sku: string;
	/**
	 * OURS, not from the payload: the snapshot time of the latest run that touched this row. NOT IN THE PRIMARY KEY (ruling A4) — it is overwritten on every run rather than appended. It is the ONLY staleness signal this table has: compare it against op_wmt_inventory_v3__run.lastSnapshotAt and treat older rows as stale, not as zero
	 */
	time: InstantColumn;
	updatedAt: InstantColumn;
}

